(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18+Math.cos(y*0.013-t*0.22)*12+Math.sin((x+y)*0.01+t*0.15)*8;
  const w1y = Math.cos(y*0.018-t*0.28)*18+Math.sin(x*0.016+t*0.32)*12+Math.cos((x-y)*0.012-t*0.18)*8;
  const w2x = Math.sin(w1x*0.025+t*0.5)*6+Math.cos(w1y*0.02-t*0.4)*4;
  const w2y = Math.cos(w1y*0.025-t*0.45)*6+Math.sin(w1x*0.022+t*0.42)*4;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,1.2],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,2.4],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,3.6],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,4.8],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.6],
    [80+Math.sin(t*0.45+3)*110,40+Math.cos(t*0.65+2)*55,0.11,2.1,2.1],
    [400+Math.cos(t*0.55+1)*95,220+Math.sin(t*0.75+4)*65,0.065,2.4,3.3]
  ];
  let aS=0,iS=0,cS=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp+ph);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5+ph*0.3);
    cS+=Math.cos(d*f*0.5-t*sp*0.8+ph*0.7);
  }
  const act=aS/8,inh=iS/8,cross=cS/8;
  const turb=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const fine=(Math.sin(sx*0.12+sy*0.08+t*2.5)+Math.sin(sx*0.09-sy*0.11+t*2.8)+Math.sin((sx+sy)*0.07-t*3.1))/3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const sp1=Math.sin(dist*0.05-ang*3-t*1.5),sp2=Math.sin(dist*0.04+ang*4-t*1.2);
  const sp3=Math.sin(dist*0.07-ang*2+t*0.9),spiral=(sp1+sp2+sp3)*0.28;
  const pulse=Math.sin(dist*0.03-t*1.8)*0.5+Math.sin(dist*0.05+t*2.2)*0.3;
  const voro=()=>{
    let md=1e9,md2=1e9,si=0;
    for(let i=0;i<12;i++){
      const vx=240+Math.sin(i*2.399+t*0.2)*160+Math.cos(i*1.7+t*0.15)*40;
      const vy=120+Math.cos(i*2.399+t*0.25)*100+Math.sin(i*1.3+t*0.18)*30;
      const d=Math.sqrt((sx-vx)**2+(sy-vy)**2);
      if(d<md){md2=md;md=d;si=i;}
      else if(d<md2)md2=d;
    }
    return Math.sin((md2-md)*0.15+si+t*0.5)*0.4;
  };
  const vCell=voro();
  const react1=Math.tanh((act-inh*0.6+cross*0.3+turb*0.25+spiral)*2.2);
  const react2=Math.tanh((inh-act*0.5-cross*0.4+fine*0.3+pulse)*1.8);
  const coupled=react1*0.7+react2*0.3+vCell*0.15;
  const edge=Math.abs(react1)>0.65?1.12:Math.abs(react1)>0.4?1.04:0.96;
  const glow=Math.exp(-Math.abs(coupled)*3)*0.3;
  const v=coupled*0.5+0.5;
  const hueShift=Math.sin(t*0.15)*0.5+0.5;
  const pal=[
    [12,22,82],[18,65,125],[20,110,135],[35,155,120],[120,180,90],[195,190,60],[215,140,65],[195,85,75],[155,50,85],[90,25,65],[45,18,72],[12,22,82]
  ];
  const hOff=hueShift*3|0;
  const len=pal.length;
  const idx=v*(len-1);
  let i=Math.min(idx|0,len-2),f=idx-i;
  i=(i+hOff)%len;
  const ni=(i+1)%len;
  const lum=0.82+Math.sin(react1*Math.PI)*0.18+glow;
  const r=pal[i][0]+(pal[ni][0]-pal[i][0])*f;
  const g=pal[i][1]+(pal[ni][1]-pal[i][1])*f;
  const b=pal[i][2]+(pal[ni][2]-pal[i][2])*f;
  return[
    Math.min(255,(r*lum*edge+glow*40)|0),
    Math.min(255,(g*lum*edge+glow*60)|0),
    Math.min(255,(b*lum*edge+glow*90)|0)
  ];
}
